import { Component, CommonModule } from '@angular/core';

@Component({
  selector: 'app-image-gallery',
  standalone: true,
  imports: [CommonModule],
  template: `
    <div class="container">
      <div *ngIf="selectedImage" class="selected-section">
        <h2>{{ selectedImage.title }}</h2>
        <img [src]="selectedImage.url" alt="{{ selectedImage.title }}" />
      </div>

      <div class="thumbnail-grid">
        <div *ngFor="let image of images" class="thumbnail">
          <img 
            [src]="image.url" 
            alt="{{ image.title }}"
            (click)="selectImage(image)"
          />
        </div>
      </div>
    </div>
  `
})
export class ImageGalleryComponent {
  images = [
    { id: 1, url: 'image1.jpg', title: 'Mountain Landscape' },
    { id: 2, url: 'image2.jpg', title: 'Ocean Sunset' },
    { id: 3, url: 'image3.jpg', title: 'Forest Path' }
  ];

  selectedImage: any = null;

  selectImage(image: any) {
    this.selectedImage = image;
  }
}

import { Component, CommonModule } from '@angular/core';

@Component({
  selector: 'app-image-gallery',
  standalone: true,
  imports: [CommonModule],
  template: `
    <div class="container">
      <div *ngIf="selectedImage" class="selected-section">
        <h2>{{ selectedImage.title }}</h2>
        <img [src]="selectedImage.url" alt="{{ selectedImage.title }}" />
      </div>

      <div class="thumbnail-grid">
        <div *ngFor="let image of images" class="thumbnail" [ngClass]="{'active': image === selectedImage}">
          <img 
            [src]="image.url" 
            alt="{{ image.title }}"
            (click)="selectImage(image)"
          />
        </div>
      </div>
    </div>
  `
})
export class ImageGalleryComponent {
  images = [
    { id: 1, url: 'image1.jpg', title: 'Mountain Landscape' },
    { id: 2, url: 'image2.jpg', title: 'Ocean Sunset' },
    { id: 3, url: 'image3.jpg', title: 'Forest Path' }
  ];

  selectedImage: any = null;

  selectImage(image: any) {
    this.selectedImage = image;
  }
}
